css:
.smd { width: 320px; padding: 24px; box-sizing: border-box; background: #fff; border-radius: 12px; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.smd-title { margin: 0 0 8px; font-size: 18px; }
.smd-text { margin: 0 0 20px; font-size: 14px; line-height: 1.7; color: #555; }
.smd-btn { padding: 10px 20px; border: 0; border-radius: 8px; background: #2563eb; color: #fff; font-size: 14px; font-weight: 600; cursor: pointer; }
.smd-btn:hover { background: #1d4ed8; }

.cfm { width: 340px; padding: 24px; box-sizing: border-box; background: #fff; border-radius: 12px; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.cfm-title { margin: 0 0 8px; font-size: 18px; }
.cfm-text { margin: 0 0 24px; font-size: 14px; line-height: 1.7; color: #555; }
.cfm-actions { display: flex; justify-content: flex-end; gap: 8px; }
.cfm-cancel, .cfm-ok { padding: 9px 18px; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer; }
.cfm-cancel { border: 1px solid #d1d5db; background: #fff; color: #374151; }
.cfm-cancel:hover { background: #f3f4f6; }
.cfm-ok { border: 1px solid #2563eb; background: #2563eb; color: #fff; }
.cfm-ok:hover { background: #1d4ed8; }

.dgr { width: 320px; padding: 28px 24px 24px; box-sizing: border-box; background: #fff; border-radius: 12px; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18); text-align: center; color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.dgr-icon { width: 48px; height: 48px; margin: 0 auto 14px; border-radius: 50%; background: #fee2e2; color: #dc2626; font-size: 26px; font-weight: 700; line-height: 48px; }
.dgr-title { margin: 0 0 8px; font-size: 18px; }
.dgr-text { margin: 0 0 22px; font-size: 13px; line-height: 1.7; color: #555; }
.dgr-actions { display: flex; gap: 8px; }
.dgr-cancel, .dgr-delete { flex: 1; padding: 10px 0; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer; }
.dgr-cancel { border: 1px solid #d1d5db; background: #fff; color: #374151; }
.dgr-delete { border: 1px solid #dc2626; background: #dc2626; color: #fff; }
.dgr-delete:hover { background: #b91c1c; }

.dne { width: 320px; padding: 28px 24px 24px; box-sizing: border-box; background: #fff; border-radius: 16px; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18); text-align: center; color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.dne-icon { width: 52px; height: 52px; margin: 0 auto 14px; border-radius: 50%; background: #dcfce7; color: #16a34a; font-size: 28px; font-weight: 700; line-height: 52px; }
.dne-title { margin: 0 0 8px; font-size: 18px; }
.dne-text { margin: 0 0 20px; font-size: 13px; line-height: 1.7; color: #555; }
.dne-btn { width: 100%; padding: 11px 0; border: 0; border-radius: 10px; background: #16a34a; color: #fff; font-size: 14px; font-weight: 600; cursor: pointer; }
.dne-btn:hover { background: #15803d; }

.fm { width: 340px; padding: 24px; box-sizing: border-box; background: #fff; border-radius: 12px; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.fm-title { margin: 0 0 4px; font-size: 18px; }
.fm-text { margin: 0 0 16px; font-size: 13px; color: #6b7280; }
.fm-label { display: block; margin-bottom: 6px; font-size: 12px; font-weight: 600; color: #374151; }
.fm-input { width: 100%; padding: 10px 12px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; font-size: 14px; }
.fm-input:focus { outline: 2px solid #bfdbfe; border-color: #2563eb; }
.fm-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 20px; }
.fm-cancel, .fm-submit { padding: 9px 16px; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer; }
.fm-cancel { border: 0; background: transparent; color: #6b7280; }
.fm-submit { border: 0; background: #2563eb; color: #fff; }
.fm-submit:hover { background: #1d4ed8; }

.im { width: 320px; overflow: hidden; background: #fff; border-radius: 14px; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.im-image { display: block; width: 100%; height: 140px; object-fit: cover; }
.im-body { padding: 18px 20px 20px; }
.im-title { margin: 0 0 6px; font-size: 17px; }
.im-text { margin: 0 0 16px; font-size: 13px; line-height: 1.7; color: #555; }
.im-btn { padding: 10px 18px; border: 0; border-radius: 999px; background: #111827; color: #fff; font-size: 13px; font-weight: 600; cursor: pointer; }
.im-btn:hover { background: #374151; }

.ch { width: 340px; overflow: hidden; background: #fff; border-radius: 12px; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ch-header { display: flex; align-items: center; justify-content: space-between; padding: 14px 18px; background: #4f46e5; color: #fff; }
.ch-title { margin: 0; font-size: 16px; }
.ch-close { border: 0; background: transparent; color: #fff; font-size: 24px; line-height: 1; cursor: pointer; }
.ch-body { margin: 0; padding: 18px; font-size: 13px; line-height: 1.8; color: #4b5563; }
.ch-footer { padding: 0 18px 18px; text-align: right; }
.ch-agree { padding: 9px 18px; border: 0; border-radius: 8px; background: #4f46e5; color: #fff; font-size: 13px; font-weight: 600; cursor: pointer; }
.ch-agree:hover { background: #4338ca; }

.sp { width: 260px; padding: 18px; box-sizing: border-box; background: #fff; border-left: 4px solid #0ea5e9; border-radius: 0 12px 12px 0; box-shadow: -4px 8px 24px rgba(0, 0, 0, 0.16); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.sp-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.sp-title { margin: 0; font-size: 16px; }
.sp-close { border: 0; background: transparent; color: #6b7280; font-size: 22px; cursor: pointer; }
.sp-list { margin: 0 0 16px; padding: 0; list-style: none; }
.sp-item { display: flex; align-items: center; justify-content: space-between; padding: 11px 2px; border-bottom: 1px solid #f1f5f9; font-size: 14px; }
.sp-check { color: #0ea5e9; font-weight: 700; }
.sp-apply { width: 100%; padding: 10px 0; border: 0; border-radius: 8px; background: #0ea5e9; color: #fff; font-size: 14px; font-weight: 600; cursor: pointer; }
.sp-apply:hover { background: #0284c7; }

.mfs { width: 360px; background: #fff; border: 1px solid #e5e7eb; border-radius: 4px; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.14); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.mfs-bar { display: flex; align-items: center; justify-content: space-between; padding: 12px 14px; border-bottom: 1px solid #e5e7eb; }
.mfs-back, .mfs-save { border: 0; background: transparent; font-size: 13px; font-weight: 600; cursor: pointer; }
.mfs-back { color: #6b7280; }
.mfs-save { color: #2563eb; }
.mfs-title { margin: 0; font-size: 15px; }
.mfs-content { padding: 6px 14px 14px; }
.mfs-row { display: flex; justify-content: space-between; gap: 12px; padding: 12px 0; border-bottom: 1px solid #f1f5f9; font-size: 13px; }
.mfs-label { color: #6b7280; }
.mfs-value { color: #111827; text-align: right; }

.cp { display: flex; align-items: center; gap: 16px; padding: 12px 14px 12px 18px; background: #fff; border: 1px solid #e5e7eb; border-radius: 999px; box-shadow: 0 6px 18px rgba(0, 0, 0, 0.12); color: #222; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.cp-text { font-size: 13px; white-space: nowrap; }
.cp-actions { display: flex; gap: 6px; }
.cp-no, .cp-yes { padding: 6px 14px; border-radius: 999px; font-size: 12px; font-weight: 600; cursor: pointer; }
.cp-no { border: 1px solid #d1d5db; background: #fff; color: #4b5563; }
.cp-yes { border: 1px solid #111827; background: #111827; color: #fff; }
